    /// exactly these arguments. The arguments in [`AgentEvent::RunDeferred`]
    /// can be redacted.
    #[must_use]
    pub fn with_deferral_slot(mut self, slot: crate::DeferralSlot) -> Self {
        self.deferral_slot = Some(slot);
