    /// newly added terminal variant from silently defaulting to non-terminal
    /// inside `AgentEvent::is_terminal`'s `matches!`.
    fn classify(ev: &AgentEvent) -> bool {
        match ev {
            AgentEvent::RunCompleted { .. }
            | AgentEvent::RunFailed { .. }
