/// The log index `k_i` of the `HandoffOccurred` event into `path[i]` for each
/// level `i` (`k_0 = 0`), all before `deferred_at`.
///
/// The search runs from the deepest level back to the root: `k_i` is the last
/// matching handoff before `k_{i+1}`. So a path that visits an agent two times
/// finds the handoffs of the latest chain.
fn handoff_indices(
    events: &[crate::SessionEvent],
    path: &[String],
    deferred_at: usize,
) -> Result<Vec<usize>, InvalidResume> {
    use crate::SessionEvent;
    let mut indices = vec![0; path.len()];
    let mut upper = deferred_at;
    for level in (1..path.len()).rev() {
        let k = events[..upper]
            .iter()
            .rposition(|e| {
                matches!(e, SessionEvent::HandoffOccurred { from, to, .. }
                    if *from == path[level - 1] && *to == path[level])
            })
            .ok_or(InvalidResume::SessionModified)?;
        indices[level] = k;
        upper = k;
    }
    Ok(indices)
}

/// `view(level, end)`: the conversation of `path[level]` over `events[..end]`.
///
/// `view(0, end)` is the projection of `events[..end]`. A child view threads
/// the parent view at its handoff (no tool items, plus a transfer note) and
/// then adds the projection of the events after the handoff.
///
/// A child view pairs each tool result with one open call of the view: the
/// result closes the earliest open call with its call id. The view drops a
/// result that closes no open call. The parent emits the transfer result after the handoff (an older
/// session can hold a late result), and the child view has no transfer
/// call. A child call can use the call id of
/// a transfer call, so a match by call id alone can keep two results for one
/// call.
fn agent_view(
    events: &[crate::SessionEvent],
    handoffs: &[usize],
    level: usize,
    end: usize,
) -> Vec<crate::Item> {
    use crate::Item;
    if level == 0 {
        return crate::project(&events[..end]).messages;
    }
    let k = handoffs[level];
    let mut view =
        crate::loop_state::thread_handoff_transcript(&agent_view(events, handoffs, level - 1, k));
    view.extend(crate::project(&events[k + 1..end]).messages);
    // The call ids of the open calls, in view order.
    let mut open: Vec<String> = Vec::new();
    view.retain(|item| match item {
        Item::ToolCall { call_id, .. } => {
            open.push(call_id.clone());
            true
        }
        Item::ToolResult { call_id, .. } => match open.iter().position(|c| c == call_id) {
            Some(p) => {
                open.remove(p);
                true
            }
            None => false,
        },
        _ => true,
    });
    view
}

/// One transfer call of a handoff response, found by its position.
///
/// Two calls on the path can have the same call id, so the call id alone
/// does not find the call. `later_calls` is the number of `ToolCalled`
/// events with the same call id after this call in the log. Each
/// conversation on the path holds every call after a transfer call of its
/// own level or deeper, so the call is the `ToolCall` item with this call id
/// that has `later_calls` such items after it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct TransferCall {
    /// The call id of the transfer call.
    pub(crate) call_id: String,
    /// The number of later `ToolCalled` events with the same call id.
    pub(crate) later_calls: usize,
}

/// The transfer calls of the handoff at `handoff_at`, in log order.
///
/// The loop records the transfer `ToolCalled` events of a handoff response
/// directly before the `HandoffOccurred` event, with the assistant text of
/// that response. A response can hold more than one transfer call; the
/// first one names the target. This finds the calls by their position, not
/// by their tool name, because a handoff can use a custom tool name.
fn transfer_calls_before(events: &[crate::SessionEvent], handoff_at: usize) -> Vec<TransferCall> {
    use crate::SessionEvent;
    let start = crate::session::transfer_run_start(events, handoff_at);
    (start..handoff_at)
        .filter_map(|at| {
            match &events[at] {
            SessionEvent::ToolCalled { call_id, .. } => Some(TransferCall {
                call_id: call_id.clone(),
                later_calls: events[at + 1..]
                    .iter()
                    .filter(|e| {
                        matches!(e, SessionEvent::ToolCalled { call_id: id, .. } if id == call_id)
                    })
                    .count(),
            }),
            _ => None,
        }
        })
        .collect()
}

